package bybit_model

/**
 * Raw log entry of one LLM call (data.llm_advice_source_response). `llmAdviceId` is None when the call failed or the
 * response could not be parsed into a valid advice, and Some(id) when it is linked to an inserted llm_advice row.
 */
case class LlmAdviceRaw(
  llmAdviceId: Option[Int],
  llmRequest: String,
  llmResponse: String
)

/** Row of data.llm_advice. `id` is generated by the sequence (pass 0, use returningGenerated). */
case class LlmAdviceInsert(
  id: Int,
  llmPromptFmId: Int,
  advice: String,
  adviceText: String,
  isSentToUser: Boolean
)

/** Insert row for data.llm_advice_source_response. `llmAdviceId` null means error or unparsable response. */
case class LlmAdviceSourceResponseInsert(
  llmAdviceId: Option[Int],
  llmRequest: String,
  llmResponse: String
)
